//! Codebase-relative advisory metrics.
//!
//! Gated metrics are judged against global calibrated thresholds; advisory
//! metrics are judged against the codebase they live in, shrunk toward a
//! per-language prior so small repositories stay stable:
//!
//! ```text
//! F̃(x) = w·F_local(x) + (1 − w)·F_lang(x),   w = n / (n + k)
//! ```
//!
//! `F_local` and `F_lang` are mid-rank empirical CDFs (ties share one value),
//! `F_lang` and `k` come from the embedded prior table generated by
//! `scripts/derive_scoring_priors.py`. With no population (`n = 0`) the
//! reading is the language-prior percentile.
//!
//! INTERFACE SKELETON — implementation lands in the relative-advisory work.

use std::collections::BTreeMap;

use crate::core::characteristic_morphism::ClassificationResult;

/// Which side of an advisory metric's distribution is unfavourable.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Direction {
    /// Larger values are worse (cyclomatic, fan-in).
    HigherWorse,
    /// Atypical in either direction is worse (instability).
    TwoSided,
}

/// `(pillar, metric, direction)` for every advisory metric.
pub const ADVISORY_METRICS: &[(&str, &str, Direction)] = &[
    ("simple", "cfg.cyclomatic", Direction::HigherWorse),
    ("simple", "cfg.nesting_depth", Direction::HigherWorse),
    ("simple", "cfg.essential", Direction::HigherWorse),
    ("composable", "mdg.fan_in", Direction::HigherWorse),
    ("composable", "mdg.instability", Direction::TwoSided),
];

/// One advisory metric read against its codebase and language prior.
#[derive(Debug, Clone, PartialEq)]
pub struct AdvisoryReading {
    pub pillar: &'static str,
    pub value: f64,
    /// Shrunk percentile `F̃(x)` in `[0, 1]` (codebase + language prior).
    pub relative_percentile: f64,
    /// Language-prior percentile `F_lang(x)`; always reported beside the
    /// relative one so a uniformly weak codebase stays visible.
    pub global_percentile: f64,
    /// `w = n / (n + k)`; `0.0` when scored without a population.
    pub local_weight: f64,
    /// Advisory quality in `(0, 1]`: `1 − F̃` (HigherWorse) or
    /// `1 − 2·|F̃ − ½|` (TwoSided).
    pub quality: f64,
    /// Atypical enough to surface as a suggestion.
    pub flagged: bool,
}

/// Per-file advisory readings without a population (language prior only).
pub fn assess(_language: &str, _raw: &BTreeMap<String, f64>) -> BTreeMap<String, AdvisoryReading> {
    BTreeMap::new()
}

/// Human-readable interpretation line for one reading (goes into
/// `ClassificationResult.interpretation` under the metric name).
pub fn interpret(_metric: &str, _reading: &AdvisoryReading) -> String {
    String::new()
}

/// Geometric mean of a pillar's advisory qualities; `1.0` when it has none.
pub fn pillar_advisory_score(pillar: &str, readings: &BTreeMap<String, AdvisoryReading>) -> f64 {
    let qualities: Vec<f64> = readings
        .values()
        .filter(|r| r.pillar == pillar)
        .map(|r| r.quality.clamp(1e-3, 1.0))
        .collect();
    if qualities.is_empty() {
        return 1.0;
    }
    (qualities.iter().map(|q| q.ln()).sum::<f64>() / qualities.len() as f64).exp()
}

/// Re-score advisories against the population `results` (one codebase),
/// then recompute each pillar score with
/// [`crate::evaluation::policies::desirability::band_score`] from the
/// stored `gate_scores`. Verdicts are never touched.
pub fn rescore_population(_results: &mut [ClassificationResult]) {}
